        cx_plastic: { cost: 0.12, cat: 'sustainability' },
        cx_pms: { cost: 0.24, cat: 'tech' },
        cx_loyalty: { cost: 0.28, cat: 'tech' },
        cx_dorm: { cost: 0.32, cat: 'talent' },
        cx_spa: { cost: 0.48, cat: 'ancillary' },
        cx_tablet: { cost: 0.36, cat: 'tech' },
        cx_av: { cost: 0.22, cat: 'group' }
    };

    class TourismRecoveryAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Tourism Recovery Playbook';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenueForecast: 51.2,
                    ebitdaMargin: 22.4,
                    capexCommitted: 0,
                    turnover: 38,
                    diagnosticBonus: 0,
                    channelBonus: 0,
                    segmentationBonus: 0,
                    mixBonus: 0,
                    talentBonus: 0,
                    primaryConstraint: '',
                    secondaryConstraint: '',
                    otaTarget: 41,
                    directTarget: 17,
                    otaPosture: '',
                    europeanPosture: '',
                    prioritySegment: '',
                    exitSegment: '',
                    fnbTarget: '',
                    capexSelected: ['cx_rooms'],
                    gstcTier: '',
                    housekeepingWage: 0,
                    fnbWage: 0,
                    retentionPrograms: [],
                    revenueHistory: [],
                    ebitdaHistory: [],
                    capexHistory: [],
                    turnoverHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    roundType: 'diagnose'
                };
            }
            this._updateBriefing(state);
            this._wireCapexListeners();
        }

        _wireCapexListeners() {
            var ids = Object.keys(CAPEX_ITEMS);
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && !el.dataset.wired) {
                    el.dataset.wired = '1';
                    el.addEventListener('change', function() {
                        var total = 0;
                        var keys = Object.keys(CAPEX_ITEMS);
                        for (var j = 0; j < keys.length; j++) {
                            var box = document.getElementById(keys[j]);
                            if (box && box.checked) total += CAPEX_ITEMS[keys[j]].cost;
                        }
                        var disp = document.getElementById('capexRunning');
                        if (disp) {
                            var capExceeded = total > 4.80;
                            disp.textContent = 'Selected: $' + total.toFixed(2) + 'M / $4.80M';
                            disp.style.background = capExceeded ? '#b85c38' : '#2a3f3f';
                            disp.style.color = '#fdf6e3';
                        }
                    });
                }
            }
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            if (period > 5) period = 5;
            var idx = period - 1;
            var meta = ROUND_META[idx];
            if (!meta) return;

            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = t(meta.titleKey);
            var leadEl = document.getElementById('briefingLead');
            if (leadEl) leadEl.textContent = t(meta.leadKey);
            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = t(meta.descKey);
            var roundTitleEl = document.getElementById('roundTitle');
            if (roundTitleEl) roundTitleEl.textContent = t(meta.titleKey);

            for (var i = 0; i < ROUND_META.length; i++) {
                var panel = document.getElementById(ROUND_META[i].panel);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }

            this._wireCapexListeners();
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            /* v1.1.0: removed pre-read DOM write; the panel refreshes on period:submitted (wired in setupUI). */

            if (period === 1) {
                var pc = document.getElementById('primaryConstraint');
                var sc = document.getElementById('secondaryConstraint');
                decisions.primaryConstraint = pc ? pc.value : '';
                decisions.secondaryConstraint = sc ? sc.value : '';
                if (!decisions.primaryConstraint || !decisions.secondaryConstraint) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r1_select'), 'warning');
                    return false;
                }
                if (decisions.primaryConstraint === decisions.secondaryConstraint) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r1_distinct'), 'warning');
                    return false;
                }
                decisions.roundType = 'diagnose';
            } else if (period === 2) {
                var ota = document.getElementById('otaTarget');
                var dir = document.getElementById('directTarget');
                var pos = document.getElementById('otaPosture');
                decisions.otaTarget = ota ? parseFloat(ota.value) : NaN;
                decisions.directTarget = dir ? parseFloat(dir.value) : NaN;
                decisions.otaPosture = pos ? pos.value : '';
                if (isNaN(decisions.otaTarget) || decisions.otaTarget < 20 || decisions.otaTarget > 50) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r2_ota'), 'warning');
                    return false;
                }
                if (isNaN(decisions.directTarget) || decisions.directTarget < 15 || decisions.directTarget > 40) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r2_direct'), 'warning');
                    return false;
                }
                if (!decisions.otaPosture) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r2_posture'), 'warning');
                    return false;
                }
                decisions.roundType = 'rechannel';
            } else if (period === 3) {
                var ep = document.getElementById('europeanPosture');
                var ps = document.getElementById('prioritySegment');
                var es = document.getElementById('exitSegment');
                decisions.europeanPosture = ep ? ep.value : '';
                decisions.prioritySegment = ps ? ps.value : '';
                decisions.exitSegment = es ? es.value : '';
                if (!decisions.europeanPosture || !decisions.prioritySegment || !decisions.exitSegment) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r3_all'), 'warning');
                    return false;
                }
                decisions.roundType = 'resegment';
            } else if (period === 4) {
                var fnb = document.getElementById('fnbTarget');
                var gstc = document.getElementById('gstcTier');
                decisions.fnbTarget = fnb ? fnb.value : '';
                decisions.gstcTier = gstc ? gstc.value : '';
                var picked = [];
                var totalCost = 0;
                var capKeys = Object.keys(CAPEX_ITEMS);
                for (var k = 0; k < capKeys.length; k++) {
                    var box = document.getElementById(capKeys[k]);
                    if (box && (box.checked || CAPEX_ITEMS[capKeys[k]].mandatory)) {
                        picked.push(capKeys[k]);
                        totalCost += CAPEX_ITEMS[capKeys[k]].cost;
                    }
                }
                decisions.capexSelected = picked;
                decisions.capexCost = totalCost;
                if (!decisions.fnbTarget || !decisions.gstcTier) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r4_select'), 'warning');
                    return false;
                }
                if (totalCost > 4.80) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_r4_capex'), 'warning');
                    return false;
                }
                decisions.roundType = 'remix';
            } else if (period === 5) {
                var hk = document.getElementById('housekeepingWage');
                var fw = document.getElementById('fnbWage');
                decisions.housekeepingWage = hk ? parseFloat(hk.value) : 0;
                decisions.fnbWage = fw ? parseFloat(fw.value) : 0;
                if (isNaN(decisions.housekeepingWage)) decisions.housekeepingWage = 0;
                if (isNaN(decisions.fnbWage)) decisions.fnbWage = 0;
                var rps = [];
                var rpKeys = ['rt_tenure', 'rt_referral', 'rt_career', 'rt_flex', 'rt_recognition'];
                for (var r = 0; r < rpKeys.length; r++) {
                    var rb = document.getElementById(rpKeys[r]);
                    if (rb && rb.checked) rps.push(rpKeys[r]);
                }
                decisions.retentionPrograms = rps;
                decisions.roundType = 'stabilise';
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var revDelta = 0;
            var ebitdaDelta = 0;
            var turnDelta = 0;
            var insight = '';
            var capexThisRound = 0;

            if (period === 1) {
                ds.primaryConstraint = d.primaryConstraint;
                ds.secondaryConstraint = d.secondaryConstraint;
                var goodPrimary = (d.primaryConstraint === 'channel' || d.primaryConstraint === 'customer');
                var goodSecondary = (d.secondaryConstraint === 'channel' || d.secondaryConstraint === 'customer');
                if (goodPrimary && goodSecondary) {
                    ds.diagnosticBonus = 0.6;
                    revDelta = 0.0;
                    ebitdaDelta = 0.2;
                    insight = window.mySimulation.t('insight_r1_excellent');
                } else if (goodPrimary || goodSecondary) {
                    ds.diagnosticBonus = 0.2;
                    revDelta = 0.0;
                    ebitdaDelta = 0.0;
                    insight = window.mySimulation.t('insight_r1_partial');
                } else {
                    ds.diagnosticBonus = -0.4;
                    revDelta = 0.0;
                    ebitdaDelta = -0.2;
                    insight = window.mySimulation.t('insight_r1_wrong');
                }
            } else if (period === 2) {
                ds.otaTarget = d.otaTarget;
                ds.directTarget = d.directTarget;
                ds.otaPosture = d.otaPosture;
                var otaDelta = 41 - d.otaTarget;
                var directDelta = d.directTarget - 17;
                var realisticOta = (otaDelta >= 2 && otaDelta <= 8);
                var aggressiveOta = (otaDelta > 8);
                var realisticDirect = (directDelta >= 2 && directDelta <= 10);
                if (realisticOta && realisticDirect) {
                    ds.channelBonus = 0.9 + ds.diagnosticBonus * 0.5;
                    ebitdaDelta = 0.6;
                    insight = window.mySimulation.t('insight_r2_balanced');
                } else if (aggressiveOta) {
                    ds.channelBonus = -0.4;
                    ebitdaDelta = -0.3;
                    insight = window.mySimulation.t('insight_r2_aggressive');
                } else if (otaDelta < 2) {
                    ds.channelBonus = 0.1;
                    ebitdaDelta = 0.1;
                    insight = window.mySimulation.t('insight_r2_timid');
                } else {
                    ds.channelBonus = 0.4;
                    ebitdaDelta = 0.3;
                    insight = window.mySimulation.t('insight_r2_partial');
                }
                if (d.otaPosture === 'renegotiate') {
                    ds.channelBonus += 0.4;
                    ebitdaDelta += 0.3;
                } else if (d.otaPosture === 'netrate') {
                    ds.channelBonus += 0.1;
                    ebitdaDelta += 0.1;
                }
                revDelta = ds.channelBonus * 0.6;
            } else if (period === 3) {
                ds.europeanPosture = d.europeanPosture;
                ds.prioritySegment = d.prioritySegment;
                ds.exitSegment = d.exitSegment;
                var segScore = 0;
                if (d.prioritySegment === 'us_premium_couples') segScore += 0.6;
                else if (d.prioritySegment === 'us_premium_family') segScore += 0.5;
                else if (d.prioritySegment === 'european_premium') segScore += 0.2;
                else if (d.prioritySegment === 'mice') segScore -= 0.1;
                if (d.exitSegment === 'mice_thin' || d.exitSegment === 'latam_regional') segScore += 0.2;
                else if (d.exitSegment === 'us_mainstream') segScore -= 0.3;
                if (d.europeanPosture === 'hybrid') segScore += 0.3;
                else if (d.europeanPosture === 'accept') segScore += 0.2;
                else if (d.europeanPosture === 'recover') segScore += 0.1;
                ds.segmentationBonus = segScore;
                revDelta = segScore * 0.8;
                ebitdaDelta = segScore * 0.3;
                if (segScore > 0.6) {
                    insight = window.mySimulation.t('insight_r3_strong');
                } else if (segScore > 0.2) {
                    insight = window.mySimulation.t('insight_r3_ok');
                } else {
                    insight = window.mySimulation.t('insight_r3_2019');
                }
            } else if (period === 4) {
                ds.fnbTarget = d.fnbTarget;
                ds.gstcTier = d.gstcTier;
                ds.capexSelected = d.capexSelected.slice();
                capexThisRound = d.capexCost - ds.capexCommitted;
                if (capexThisRound < 0) capexThisRound = d.capexCost;
                ds.capexCommitted = d.capexCost;
                var mixScore = 0;
                var hasSelva = d.capexSelected.indexOf('cx_selva') !== -1;
                var hasFnbEquip = d.capexSelected.indexOf('cx_fnb_equip') !== -1;
                var hasEnergy = d.capexSelected.indexOf('cx_energy') !== -1;
                var hasWater = d.capexSelected.indexOf('cx_water') !== -1;
                var hasPms = d.capexSelected.indexOf('cx_pms') !== -1;
                var hasLoyalty = d.capexSelected.indexOf('cx_loyalty') !== -1;
                var hasDorm = d.capexSelected.indexOf('cx_dorm') !== -1;

                if (d.fnbTarget === 'lift') {
                    mixScore += 0.6;
                    if (hasSelva && hasFnbEquip) mixScore += 0.4;
                    else mixScore -= 0.2;
                } else if (d.fnbTarget === 'defend') {
                    mixScore += 0.1;
                } else if (d.fnbTarget === 'ancillary') {
                    mixScore -= 0.2;
                }

                if (d.gstcTier === 'full') {
                    if (hasEnergy && hasWater) {
                        mixScore += 0.5;
                        if (ds.europeanPosture === 'recover' || ds.europeanPosture === 'hybrid') mixScore += 0.3;
                    } else {
                        mixScore -= 0.3;
                    }
                } else if (d.gstcTier === 'basic') {
                    if (hasEnergy || hasWater) mixScore += 0.2;
                }

                if (hasPms || hasLoyalty) mixScore += 0.2;
                if (hasDorm) mixScore += 0.1;

                ds.mixBonus = mixScore;
                revDelta = mixScore * 0.7;
                ebitdaDelta = mixScore * 0.3;

                if (mixScore > 0.8) {
                    insight = window.mySimulation.t('insight_r4_strong');
                } else if (mixScore > 0.3) {
                    insight = window.mySimulation.t('insight_r4_ok');
                } else {
                    insight = window.mySimulation.t('insight_r4_weak');
                }
            } else if (period === 5) {
                ds.housekeepingWage = d.housekeepingWage;
                ds.fnbWage = d.fnbWage;
                ds.retentionPrograms = d.retentionPrograms.slice();
                var avgWageLift = (d.housekeepingWage + d.fnbWage) / 2;
                var rpCount = d.retentionPrograms.length;
                var talentScore = 0;
                if (avgWageLift >= 12 && avgWageLift <= 18 && rpCount >= 2) {
                    talentScore = 1.0;
                    turnDelta = -16;
                    insight = window.mySimulation.t('insight_r5_invert');
                } else if (avgWageLift >= 8 && rpCount >= 1) {
                    talentScore = 0.5;
                    turnDelta = -9;
                    insight = window.mySimulation.t('insight_r5_partial');
                } else if (avgWageLift > 18) {
                    talentScore = 0.3;
                    turnDelta = -18;
                    ebitdaDelta -= 0.3;
                    insight = window.mySimulation.t('insight_r5_overshoot');
                } else {
                    talentScore = -0.3;
                    turnDelta = +2;
                    insight = window.mySimulation.t('insight_r5_conservative');
                }
                ds.talentBonus = talentScore;
                revDelta = talentScore * 0.4;
                ebitdaDelta += talentScore * 0.5;

                var totalRev = 51.2;
                totalRev += (ds.diagnosticBonus || 0) * 0.4;
                totalRev += (ds.channelBonus || 0) * 0.6;
                totalRev += (ds.segmentationBonus || 0) * 0.8;
                totalRev += (ds.mixBonus || 0) * 0.7;
                totalRev += (ds.talentBonus || 0) * 0.4;
                ds.revenueForecast = Math.round(totalRev * 100) / 100;

                var totalEb = 22.4;
                totalEb += (ds.diagnosticBonus || 0) * 0.2;
                totalEb += (ds.channelBonus || 0) * 0.5;
                totalEb += (ds.segmentationBonus || 0) * 0.3;
                totalEb += (ds.mixBonus || 0) * 0.3;
                totalEb += (ds.talentBonus || 0) * 0.5;
                ds.ebitdaMargin = Math.round(totalEb * 100) / 100;
            }

            if (period < 5) {
                ds.revenueForecast = Math.round((ds.revenueForecast + revDelta) * 100) / 100;
                ds.ebitdaMargin = Math.round((ds.ebitdaMargin + ebitdaDelta) * 100) / 100;
            }
            ds.turnover = Math.max(8, Math.round(ds.turnover + turnDelta));

            ds.revenueHistory.push(ds.revenueForecast);
            ds.ebitdaHistory.push(ds.ebitdaMargin);
            ds.capexHistory.push(ds.capexCommitted);
            ds.turnoverHistory.push(ds.turnover);

            // SCORE: overallScore scales the same 0 to 8 greenCount composite that
            // getPerformanceSummary uses for its verdict thresholds onto 0-100, rounded and clamped
            var scoreGreen = 0;
            if (ds.revenueForecast >= 55.3) scoreGreen++;
            if (ds.ebitdaMargin >= 23.6) scoreGreen++;
            if (ds.capexCommitted <= 4.80 && ds.capexCommitted >= 3.5) scoreGreen++;
            if (ds.turnover < 28) scoreGreen++;
            if ((ds.diagnosticBonus || 0) > 0.4) scoreGreen++;
            if ((ds.channelBonus || 0) > 0.5) scoreGreen++;
            if ((ds.segmentationBonus || 0) > 0.3) scoreGreen++;
            if ((ds.mixBonus || 0) > 0.4) scoreGreen++;
            var overallScore = Math.round(100 * scoreGreen / 8);
            if (overallScore < 0) overallScore = 0;
            if (overallScore > 100) overallScore = 100;
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: overallScore });

            return {
                period: period,
                roundType: d.roundType,
                revenueForecast: ds.revenueForecast,
                ebitdaMargin: ds.ebitdaMargin,
                capexCommitted: ds.capexCommitted,
                capexThisRound: capexThisRound,
                turnover: ds.turnover,
                revDelta: Math.round(revDelta * 100) / 100,
                ebitdaDelta: Math.round(ebitdaDelta * 100) / 100,
                turnDelta: turnDelta,
                insight: insight,
                primaryConstraint: d.primaryConstraint || ds.primaryConstraint,
                otaTarget: d.otaTarget,
                directTarget: d.directTarget,
                europeanPosture: d.europeanPosture || ds.europeanPosture,
                fnbTarget: d.fnbTarget || ds.fnbTarget,
                gstcTier: d.gstcTier || ds.gstcTier,
                wageLift: ((d.housekeepingWage || 0) + (d.fnbWage || 0)) / 2
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.revenueForecast', function(v) { return '$' + v.toFixed(1) + 'M'; });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaMargin', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('capexDisplay', 'domainState.capexCommitted', function(v) { return '$' + v.toFixed(2) + 'M'; });
            uiManager.bind('turnoverDisplay', 'domainState.turnover', function(v) { return Math.round(v) + '%'; });

            /* v1.1.0 FIX: the view uses a non-standard data-i18n-option attribute on
               select options that the player shim does not translate; apply it ourselves
               at render time and again whenever the language changes, so no English
               option text (Maintain, Renegotiate, Shift to net-rate...) survives in Spanish. */
            this._applyOptionI18n();

            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); _self._applyOptionI18n(); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

        _applyOptionI18n() {
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var opts = document.querySelectorAll('option[data-i18n-option]');
            for (var i = 0; i < opts.length; i++) {
                opts[i].textContent = t(opts[i].getAttribute('data-i18n-option'));
            }
        }

        getChartConfig() {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            return {
                performanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t('chart_ds_revenue'),
                                data: [],
                                borderColor: '#0d6e6e',
                                backgroundColor: 'rgba(13,110,110,0.12)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: t('chart_ds_ebitda'),
                                data: [],
                                borderColor: '#c9a449',
                                backgroundColor: 'rgba(201,164,73,0.12)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            },
                            {
                                label: t('chart_ds_target'),
                                data: [],
                                borderColor: '#b85c38',
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                pointRadius: 0,
                                yAxisID: 'y'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_title') },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                position: 'left',
                                title: { display: true, text: t('chart_axis_revenue') },
                                suggestedMin: 48,
                                suggestedMax: 58
                            },
                            y1: {
                                type: 'linear',
                                position: 'right',
                                title: { display: true, text: t('chart_axis_ebitda') },
                                grid: { drawOnChartArea: false },
                                suggestedMin: 20,
                                suggestedMax: 26
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'R' + (i + 1); });
            var targetLine = state.domainState.revenueHistory.map(function() { return 55.3; });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.ebitdaHistory },
                        { data: targetLine }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : {};
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var finalRev = ds.revenueForecast || 51.2;
            var finalEb = ds.ebitdaMargin || 22.4;
            var finalCapex = ds.capexCommitted || 0;
            var finalTurn = ds.turnover || 38;

            var revenueGap = finalRev - 55.3;
            var ebitdaGap = finalEb - 23.6;
            var capexOk = finalCapex <= 4.80 && finalCapex >= 3.5;
            var turnoverOk = finalTurn < 28;

            var greenCount = 0;
            if (finalRev >= 55.3) greenCount++;
            if (finalEb >= 23.6) greenCount++;
            if (capexOk) greenCount++;
            if (turnoverOk) greenCount++;
            if (ds.diagnosticBonus > 0.4) greenCount++;
            if (ds.channelBonus > 0.5) greenCount++;
            if (ds.segmentationBonus > 0.3) greenCount++;
            if (ds.mixBonus > 0.4) greenCount++;

            var verdict = '';
            var insights = [];
            if (greenCount >= 6 && finalRev >= 55.3 && finalEb >= 23.6) {
                verdict = t('summary_verdict_signed');
                insights.push(t('summary_insight_reconciles'));
                insights.push(t('summary_insight_reinforce'));
            } else if (greenCount >= 4 && capexOk) {
                verdict = t('summary_verdict_caveat');
                insights.push(t('summary_insight_defensible'));
                insights.push(t('summary_insight_inconsistencies'));
            } else {
                verdict = t('summary_verdict_revision');
                insights.push(t('summary_insight_missed'));
                if (revenueGap < -1) insights.push(t('summary_insight_revenue_gap'));
                if (ebitdaGap < -0.5) insights.push(t('summary_insight_ebitda_gap'));
                if (!capexOk) insights.push(t('summary_insight_capex_misused'));
                if (!turnoverOk) insights.push(t('summary_insight_turnover_high'));
            }

            return {
                verdict: verdict,
                forecastRevenue: finalRev,
                forecastEbitda: finalEb,
                capexCommitted: finalCapex,
                projectedTurnover: finalTurn,
                greenMetrics: greenCount,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;
            var ds = state.domainState;
            if (period === 2 && (ds.diagnosticBonus || 0) < 0) return window.mySimulation.t('hint_r2_after_wrong_diagnosis');
            if (period === 3 && ds.otaTarget > 38) return window.mySimulation.t('hint_r3_ota_too_high');
            if (period === 4 && ds.gstcTier === 'full' && ds.capexSelected.indexOf('cx_energy') === -1) return window.mySimulation.t('hint_r4_gstc_inconsistent');
            if (period === 5 && (ds.housekeepingWage || 0) === 0 && (ds.fnbWage || 0) === 0) return window.mySimulation.t('hint_r5_no_wage');
            if (results.insight) return results.insight;
            return null;
        }

